import json
import time

URL = "https://tong.com.vn/dat-ban"
HOUR_VALUE = HHMM + ":00"
PARTY_STR = str(PARTY)
DAY_TEXT = "Ngày mai"
BRANCH_TEXT = "Tòng Livehouse"


def poll_js(expr, timeout=15.0, step=0.2):
    """Gọi biểu thức JS (dạng IIFE) lặp lại: tối đa `timeout` giây, mỗi lần cách `step` giây."""
    end = time.time() + timeout
    last = None
    while time.time() < end:
        last = js(expr)
        if last:
            return last
        time.sleep(step)
    raise RuntimeError("Timeout: " + expr[:120] + " | last=" + repr(last))


def element_exists(sel_id):
    return bool(js("return !!document.getElementById(%s)" % json.dumps(sel_id)))


def set_select(sel_id, want_value=None, want_text=None):
    """Tìm option theo value hoặc text, gán value, dispatch input và change."""
    expr = """(() => {
      const s = document.getElementById(%s);
      if (!s) return {err: 'no select'};
      const wv = %s, wt = %s;
      const o = [...s.options].find(o =>
        (wv !== null && o.value === wv) || (wt !== null && o.text.trim() === wt));
      if (!o) return {err: 'no option', opts: [...s.options].map(o => o.value + '|' + o.text)};
      s.value = o.value;
      s.dispatchEvent(new Event('input', {bubbles: true}));
      s.dispatchEvent(new Event('change', {bubbles: true}));
      return {ok: true, value: s.value};
    })()""" % (json.dumps(sel_id), json.dumps(want_value), json.dumps(want_text))
    r = js(expr)
    if not r or not r.get("ok"):
        raise RuntimeError("Không chọn được %s: %s" % (sel_id, r))
    return r


def fill_text(selector, txt):
    """Focus ô bằng CDP rồi chọn toàn bộ và gõ nội dung mới."""
    n = cdp('DOM.getDocument')['root']['nodeId']
    nid = cdp('DOM.querySelector', nodeId=n, selector=selector)['nodeId']
    if not nid:
        raise RuntimeError("Không tìm thấy ô: " + selector)
    bid = cdp('DOM.describeNode', nodeId=nid)['node']['backendNodeId']
    cdp('DOM.scrollIntoViewIfNeeded', backendNodeId=bid)
    cdp('DOM.focus', backendNodeId=bid)
    cdp('Input.dispatchKeyEvent', type='rawKeyDown', key='a', code='KeyA', commands=['selectAll'])
    cdp('Input.dispatchKeyEvent', type='keyUp', key='a', code='KeyA')
    type_text(txt)


def get_hour_state():
    return js("""return (() => {
      const s = document.getElementById('selectHour');
      if (!s) return null;
      return {v: s.value, disabled: s.disabled, opts: [...s.options].map(o => o.value)};
    })()""")


def hour_ready(st):
    return bool(st) and not st["disabled"] and HOUR_VALUE in st["opts"]


def wait_hour_list_stable(timeout=15.0, step=0.2, stable_polls=5):
    """Chờ danh sách giờ có HOUR_VALUE và không đổi trong ~1 giây (tải xong)."""
    end = time.time() + timeout
    prev = None
    streak = 0
    while time.time() < end:
        st = get_hour_state()
        if hour_ready(st):
            key = json.dumps(st["opts"])
            if key == prev:
                streak += 1
            else:
                prev = key
                streak = 1
            if streak >= stable_polls:
                return
        else:
            prev = None
            streak = 0
        time.sleep(step)
    raise RuntimeError("Danh sách giờ chưa tải xong hoặc thiếu giá trị " + HOUR_VALUE)


def choose_hour(max_try=4):
    """Chọn giờ; nếu trang reset giờ về 'Chọn' thì chờ danh sách ổn định và chọn lại."""
    for _ in range(max_try):
        wait_hour_list_stable()
        set_select("selectHour", want_value=HOUR_VALUE, want_text=HHMM)
        stuck = True
        for _ in range(5):  # giữ kiểm tra khoảng 1 giây
            time.sleep(0.2)
            st = get_hour_state()
            if not st or st["v"] != HOUR_VALUE:
                stuck = False
                break
        if stuck:
            return
    raise RuntimeError("Giờ bị reset sau %d lần chọn" % max_try)


# 1. Mở trang và chờ các phần tử chính
new_tab(URL)
wait_for_load()
poll_js("""(() => !!document.getElementById('selectSoNguoi')
            && !!document.getElementById('selectDay')
            && !!document.getElementById('selectHour')
            && !!document.getElementById('nameOrder')
            && !!document.getElementById('sdtOrder'))()""")

# 2. Chi nhánh: chỉ chọn nếu có option đúng tên (giữ như bản cũ)
if element_exists("selectCoso"):
    has_branch = js("""return (() => {
      const s = document.getElementById('selectCoso');
      return [...s.options].some(o => o.text.trim() === %s);
    })()""" % json.dumps(BRANCH_TEXT))
    if has_branch:
        set_select("selectCoso", want_text=BRANCH_TEXT)

# 3. Số người
set_select("selectSoNguoi", want_value=PARTY_STR)

# 4. Ngày (đặt trước giờ vì danh sách giờ phụ thuộc ngày)
set_select("selectDay", want_text=DAY_TEXT)

# 5. Giờ: chờ danh sách tải xong rồi chọn, chọn lại nếu bị reset
choose_hour()

# 6. Điền các ô (bỏ qua ô không tồn tại)
fill_text("#nameOrder", NAME)
fill_text("#sdtOrder", PHONE)

email_exists = js("return !!document.querySelector('input[type=email]')")
if email_exists:
    email_id = js("return document.querySelector('input[type=email]').id || ''")
    email_sel = ("#" + email_id) if email_id else "input[type=email]"
    fill_text(email_sel, EMAIL)

# 7. Sau khi điền, kiểm tra lại giờ; nếu bị đổi thì chọn lại
st = get_hour_state()
if not st or st["v"] != HOUR_VALUE:
    choose_hour()

# 8. Kiểm tra giá trị các ô, raise nếu sai
state = js("""return (() => {
  const g = id => document.getElementById(id);
  const sel = g('selectDay');
  const em = document.querySelector('input[type=email]');
  return {
    party: g('selectSoNguoi') ? g('selectSoNguoi').value : null,
    dayText: sel && sel.selectedOptions[0] ? sel.selectedOptions[0].text.trim() : null,
    hour: g('selectHour') ? g('selectHour').value : null,
    name: g('nameOrder') ? g('nameOrder').value : null,
    phone: g('sdtOrder') ? g('sdtOrder').value : null,
    emailEl: !!em,
    email: em ? em.value : null
  };
})()""")

errors = []
if str(state.get("party")) != PARTY_STR:
    errors.append("số người: %r" % state.get("party"))
if state.get("dayText") != DAY_TEXT:
    errors.append("ngày: %r" % state.get("dayText"))
if state.get("hour") != HOUR_VALUE:
    errors.append("giờ: %r" % state.get("hour"))
if state.get("name") != NAME:
    errors.append("tên: %r" % state.get("name"))
if state.get("phone") != PHONE:
    errors.append("SĐT: %r" % state.get("phone"))
if state.get("emailEl") and state.get("email") != EMAIL:
    errors.append("email: %r" % state.get("email"))

if errors:
    raise RuntimeError("Giá trị ô không đúng: " + "; ".join(errors) + " | state=" + json.dumps(state, ensure_ascii=False))

print("OK:", json.dumps(state, ensure_ascii=False))

